SELECT a.tenant_id,a.grid_id, a.province_code, a.city_code, a.county_code, a.town_code, a.province_name, a.city_name, a.county_name, a.town_name, a.device_code, CONCAT( ifnull(province_name, '省'), ifnull(city_name, '市'), ifnull(county_name, '区'), ifnull(town_name, '街道') ) AS 'regionName', count(DISTINCT a.warning_order_id) AS warning_num, DATE_FORMAT(a.alarm_time, '%Y') AS year_str, DATE_FORMAT(a.alarm_time, '%c') AS month_str, DATE_FORMAT(a.alarm_time, '%e') AS day_str, alarm_time, #{handleDateTime} AS 'handleDateTime', a.app_ver_code, a.warning_source, a.industry_code industry_code, COUNT( IF ( a.judge_result = '1', 1, NULL )) AS real_num, COUNT(IF(a.order_status = '0', 1, NULL)) AS false_num, COUNT(IF ( a.order_status = '7', 1, NULL )) AS repeat_complete_num FROM ${tableName} a WHERE delete_flag = '0'
and DATE_FORMAT(alarm_time, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(alarm_time, '%Y-%m') = #{handleDate}
GROUP BY a.tenant_id, a.province_code, a.city_code, a.county_code, a.town_code, a.device_code, a.app_ver_code, a.industry_code, a.warning_source,a.grid_id, DATE_FORMAT(alarm_time, '%Y-%m-%d')

SELECT t.tenant_id as tenantId, t.industry_code as industryCode, t.plan_task_id as taskRecordId, t.plan_time as planExecuteTime, t.reality_time as actualExecuteTime, p.plan_type as taskStrategy, p.plan_id as planId, p.plan_name as planName, al.extra_field as waypointCoordinates, al.air_mileage as routeTotalDistance, al.flight_route_id as flightRouteId, al.flight_route_name as flightRouteName, t.fly_time as flightDuration, d.device_code as uavCode, d.device_name as uavName, d.uav_nest_code as uavNestCode, n.device_name as uavNestName, m.model_code as uavModelCode, m.model_name as uavModelName, t.create_user as taskCreator, t.task_status, NOW() as createdAt FROM vm_air_task_t t LEFT JOIN vm_air_plan_t p ON t.plan_id = p.plan_id and p.delete_flag = '0' LEFT JOIN vm_air_line_t al ON t.flight_route_id = al.flight_route_id and al.delete_flag = '0' LEFT JOIN vm_uav_device_info_t d ON t.uav_code = d.device_code COLLATE utf8mb4_general_ci and d.delete_flag = '0' LEFT JOIN vm_uav_nest_device_info n ON d.uav_nest_code = n.device_code and n.delete_flag = '0' LEFT JOIN vm_uav_device_model_t m ON d.model_code = m.model_code and m.delete_flag = '0' WHERE t.delete_flag = '0'
and DATE_FORMAT(t.plan_time, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(t.plan_time, '%Y-%m') = #{handleDate}

