and DATE_FORMAT(alarm_time, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(alarm_time, '%Y-%m') = #{handleDate}
) a GROUP BY a.tenant_id, a.county_code, a.device_code, a.emergency_level, a.app_ver_code, a.industry_code, a.province_code, a.city_code, a.warning_source, DATE_FORMAT(a.alarm_time, '%Y-%m-%d')

