SELECT ord.tenant_id, ord.province_code AS province_id, ord.city_code AS city_id, ord.county_code AS 'countyId', ord.device_code, COUNT(if(UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) < '3600', 1, NULL)) AS 'lessOne', COUNT(if(UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) >= '3600' AND UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) <= '18000', 1, NULL)) AS 'oneFive', COUNT(if(UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) > '18000' AND UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) <= '36000', 1, NULL)) AS 'fiveTen', COUNT(if(UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) > '36000', 1, NULL)) AS 'moreTen', ord.app_ver_code, ord.warning_source, ord.industry_code as industry_code, ord.modifier_date, ord.alarm_time, year(ord.modifier_date) as year_str, MONTH(ord.modifier_date) as month_str, DAY(ord.modifier_date) as day_str FROM ${tableName} ord WHERE ord.delete_flag = '0' AND ord.order_status IN('0','6','7')
AND DATE_FORMAT(ord.modifier_date, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(ord.modifier_date, '%Y-%m') = #{handleDate}
GROUP BY ord.tenant_id, ord.province_code, ord.city_code, ord.county_code, ord.device_code, ord.app_ver_code, ord.industry_code, ord.warning_source ,DATE_FORMAT(ord.modifier_date, '%Y-%m-%d'),DATE_FORMAT(ord.alarm_time, '%Y-%m-%d')

SELECT aa.tenant_id, IFNULL(aa.province_code, 'null') AS province_id, IFNULL(aa.city_code, 'null') AS city_id, IFNULL(aa.county_code, 'null') AS county_id, IFNULL( aa.town_code, 'null' ) AS town_id, aa.device_code,aa.device_name,aa.grid_id,aa.grid_name,aa.importance_level as alarm_level, COUNT(if(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate}, 1, NULL)) AS today_all, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status IN ('0', '7', '6'), 1, NULL)) AS today_complete, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '0', 1, NULL)) AS false_complete_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '1' AND aa.enable_acceptance_mode !='1', 1, NULL)) AS judge_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '2' AND aa.enable_acceptance_mode !='1', 1, NULL)) AS dispatch_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '3' AND aa.enable_acceptance_mode !='1', 1, NULL)) AS grab_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '4' AND aa.enable_acceptance_mode !='1', 1, NULL)) AS handle_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '5' AND aa.enable_acceptance_mode !='1', 1, NULL)) AS approve_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '6', 1, NULL)) AS order_complete_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '7', 1, NULL)) AS repeat_complete_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status = '0', 1, NULL)) AS false_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.judge_result = '1', 1, NULL)) AS real_num, COUNT(IF( DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.enable_acceptance_mode = '1', 1, NULL )) AS acceptance_num, SUM( IF (DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status IN ( '0', '7', '6' ), duration, NULL )) AS duration, SUM( IF (DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status IN ('0'), duration, NULL )) AS false_duration, SUM( IF (DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status IN ('6'), duration, NULL )) AS order_complete_duration, SUM( IF (DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status IN ('7'), duration, NULL )) AS repeat_duration, SUM( IF (DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.order_status IN ('6') AND aa.judge_result = '1', duration, NULL )) AS order_complete_real_duration, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.warning_source = '1', 1, NULL)) AS ai_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.warning_source = '2', 1, NULL)) AS manual_num, COUNT(IF(DATE_FORMAT(aa.alarm_time, '%Y-%m-%d') = #{handleDate} AND aa.warning_source = '3', 1, NULL)) AS onekey_num, COUNT( IF ( aa.order_status = '1' AND aa.enable_acceptance_mode !='1' AND aa.judge_result = '1', 1, NULL ) ) AS judge_real_num, COUNT( IF ( aa.order_status = '2' AND aa.enable_acceptance_mode !='1' AND aa.judge_result = '1', 1, NULL ) ) AS dispatch_real_num, COUNT( IF ( aa.order_status = '4' AND aa.enable_acceptance_mode !='1' AND aa.judge_result = '1', 1, NULL ) ) AS handle_real_num, COUNT( IF ( aa.order_status = '5' AND aa.enable_acceptance_mode !='1' AND aa.judge_result = '1', 1, NULL ) ) AS approve_real_num, COUNT( IF ( aa.order_status = '6' AND aa.judge_result = '1', 1, NULL ) ) AS order_complete_real_num, COUNT( IF ( aa.enable_acceptance_mode = '1' AND aa.judge_result = '1', 1, NULL )) AS acceptance_real_num, YEAR ( #{handleDate}) as year_str, MONTH ( #{handleDate}) as month_str, DAY ( #{handleDate}) as day_str, #{handleDateTime} as 'handleDateTime', aa.app_ver_code, aa.warning_source, aa.warning_type_id, aa.industry_code as industry_code FROM ( SELECT ord.tenant_id, ord.province_code, ord.city_code, ord.county_code,ord.town_code, ord.device_code,ord.device_name, ord.alarm_time, ord.order_status, ord.warning_source,ord.warning_type_id , ord.app_ver_code, ord.industry_code,ord.judge_result,ord.enable_acceptance_mode,ord.grid_id,ord.grid_name,ord.importance_level, UNIX_TIMESTAMP(ord.modifier_date) - UNIX_TIMESTAMP(ord.alarm_time) AS duration FROM ${tableName} ord WHERE ord.delete_flag = '0'
and DATE_FORMAT(ord.alarm_time, '%Y-%m-%d') = #{handleDate}
and DATE_FORMAT(ord.alarm_time, '%Y-%m') = #{handleDate}
